mapper.select:
SELECT
id,scope_code,dimension_type,dimension_key,display_name,author_name,institution_name,stat_year,publication_count
FROM research_stat_dimension
WHERE snapshot_id=#{snapshotId} AND scope_code=#{scopeCode} AND dimension_type=#{type}
ORDER BY publication_count DESC LIMIT #{limit}

SELECT COUNT(*) FROM research_stat_dimension_publication r
JOIN research_stat_dimension d ON d.id=r.dimension_id
WHERE d.snapshot_id=#{snapshotId} AND d.id=#{dimensionId}

SELECT r.publication_key FROM research_stat_dimension_publication r
JOIN research_stat_dimension d ON d.id=r.dimension_id
WHERE d.snapshot_id=#{snapshotId} AND d.id=#{dimensionId}
ORDER BY r.publication_key LIMIT #{size} OFFSET #{offset}
